        func encoded() throws(GesWireError) -> [UInt8] {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(Self.maxByteCount, 1), alignment: 8)
            defer { buffer.deallocate() }
            let count = try write(into: buffer)
            return Array(buffer[0..<count])
        }

        /// Reads a record from untrusted data into this instance. After an error its values are unspecified.
        /// - Parameters:
        ///   - data: The data; it may continue after the record.
        ///   - byteLimit: An optional limit on the bytes of this record.
        /// - Returns: The number of bytes the record occupies.
        /// - Throws: `GesWireError` when the data is no valid record.
        @discardableResult
        func read(from data: UnsafeRawBufferPointer, byteLimit: Int = .max) throws(GesWireError) -> Int {
            var reader = GesBitReader(data: data, byteLimit: byteLimit)
            try __readFields(&reader, Self.__paths, 0)
            return try reader.finish()
        }

        /// Reads a record from bytes into this instance. After an error its values are unspecified.
        /// - Returns: The number of bytes the record occupies.
        /// - Throws: `GesWireError` when the bytes are no valid record.
        @discardableResult
        func read(from bytes: [UInt8], byteLimit: Int = .max) throws(GesWireError) -> Int {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(bytes.count, 1), alignment: 8)
            defer { buffer.deallocate() }
            buffer.copyBytes(from: bytes)
            return try read(from: UnsafeRawBufferPointer(rebasing: buffer[0..<bytes.count]), byteLimit: byteLimit)
        }

        /// Reads the key, which comes first, before a caller chooses a baseline.
        /// - Throws: `GesWireError` when the data ends before the key does or holds an invalid key.
        static func readKey(from data: UnsafeRawBufferPointer) throws(GesWireError) -> Int64 {
            var reader = GesBitReader(data: data)
            let paths = Self.__paths
            let at = 0
            var key: Int64 = 0
            do {
                let index = try reader.read(16, path: paths[at + 0])
                key = Int64(bitPattern: 0 &+ index)
            }
            return key
        }

        func __writeFields(_ writer: inout GesBitWriter, _ paths: [String], _ at: Int) throws(GesWireError) {
            if self.id < 0 || UInt64(bitPattern: self.id) &- 0 > 65535 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 0]) }
            try writer.write(UInt64(bitPattern: self.id) &- 0, width: 16)
            try self.pose.__writeFields(&writer, paths, at + 2)
            if self.health < 0 || UInt64(bitPattern: self.health) &- 0 > 100 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 5]) }
            try writer.write(UInt64(bitPattern: self.health) &- 0, width: 7)
            try writer.write(self.firing ? 1 : 0, width: 1)
            if self.hasTarget {
                try writer.write(1, width: 1)
                if self.target < 0 || UInt64(bitPattern: self.target) &- 0 > 65535 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 7]) }
                try writer.write(UInt64(bitPattern: self.target) &- 0, width: 16)
            } else {
                try writer.write(0, width: 1)
            }
            if self.nameUTF8.count > 12 { throw GesWireError(code: GesWireError.tooLong, path: paths[at + 8]) }
            if !self.nameUTF8.withUnsafeBytes({ GesWireRules.isValidUTF8($0) }) { throw GesWireError(code: GesWireError.invalidText, path: paths[at + 8]) }
            try writer.write(UInt64(self.nameUTF8.count), width: 4)
            for byte in self.nameUTF8 { try writer.write(UInt64(byte), width: 8) }
        }

        func __readFields(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) {
            do {
                let index = try reader.read(16, path: paths[at + 0])
                self.id = Int64(bitPattern: 0 &+ index)
            }
            try self.pose.__readFields(&reader, paths, at + 2)
            do {
                let index = try reader.read(7, path: paths[at + 5])
                if index > 100 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 5]) }
                self.health = Int64(bitPattern: 0 &+ index)
            }
            self.firing = try reader.read(1, path: paths[at + 6]) != 0
            self.hasTarget = try reader.read(1, path: paths[at + 7]) != 0
            if self.hasTarget {
                do {
                    let index = try reader.read(16, path: paths[at + 7])
                    self.target = Int64(bitPattern: 0 &+ index)
                }
            } else {
                self.target = 0
            }
            do {
                let count = Int(try reader.read(4, path: paths[at + 8]))
                if count > 12 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 8]) }
                try reader.require(count * 8, path: paths[at + 8])
                self.nameUTF8.removeAll(keepingCapacity: true)
                for _ in 0..<count { self.nameUTF8.append(UInt8(truncatingIfNeeded: try reader.read(8, path: paths[at + 8]))) }
                if !self.nameUTF8.withUnsafeBytes({ GesWireRules.isValidUTF8($0) }) { throw GesWireError(code: GesWireError.invalidText, path: paths[at + 8]) }
            }
        }

        func __mark(_ busy: Bool) { self.__busy = busy }

        func __holds() -> Bool { self.__busy }

        private func __same8(_ baseline: Ship, _ paths: [String], _ at: Int) throws(GesWireError) -> Bool {
            if self.nameUTF8 != baseline.nameUTF8 { return false }
            return true
        }

        private static func __wire0(_ value: Int64, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            if value < 0 || UInt64(bitPattern: value) &- 0 > 65535 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 0]) }
            return UInt64(bitPattern: value) &- 0
        }

        private static func __read0(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(16, path: paths[at + 0])
            return wire
        }

        private static func __value0(_ wire: UInt64) -> Int64 { Int64(bitPattern: 0 &+ wire) }

        private static func __wire5(_ value: Int64, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            if value < 0 || UInt64(bitPattern: value) &- 0 > 100 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 5]) }
            return UInt64(bitPattern: value) &- 0
        }

        private static func __read5(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(7, path: paths[at + 5])
            if wire > 100 { throw GesWireError(code: GesWireError.invalidIndex, path: paths[at + 5]) }
            return wire
        }

        private static func __value5(_ wire: UInt64) -> Int64 { Int64(bitPattern: 0 &+ wire) }

        private static func __wire6(_ value: Bool, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            value ? 1 : 0
        }

        private static func __read6(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(0, path: paths[at + 6])
            return wire
        }

        private static func __value6(_ wire: UInt64) -> Bool { wire != 0 }

        private static func __wire7(_ value: Int64, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            if value < 0 || UInt64(bitPattern: value) &- 0 > 65535 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 7]) }
            return UInt64(bitPattern: value) &- 0
        }

        private static func __read7(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            let wire = try reader.read(16, path: paths[at + 7])
            return wire
        }

        private static func __value7(_ wire: UInt64) -> Int64 { Int64(bitPattern: 0 &+ wire) }

        func __same(_ other: Ship, _ paths: [String], _ at: Int) throws(GesWireError) -> Bool {
            if try Self.__wire0(self.id, paths, at) != Self.__wire0(other.id, paths, at) { return false }
            if !(try self.pose.__same(other.pose, paths, at + 2)) { return false }
            if try Self.__wire5(self.health, paths, at) != Self.__wire5(other.health, paths, at) { return false }
            if self.firing != other.firing { return false }
            if self.hasTarget != other.hasTarget { return false }
            if self.hasTarget {
                if try Self.__wire7(self.target, paths, at) != Self.__wire7(other.target, paths, at) { return false }
            }
            if self.nameUTF8 != other.nameUTF8 { return false }
            return true
        }

        /// Copies the values of another record into the storage of this one, without allocating once it has grown.
        func copy(from other: Ship) {
            if self === other { return }
            self.id = other.id
            self.pose = other.pose
            self.health = other.health
            self.firing = other.firing
            self.hasTarget = other.hasTarget
            self.target = other.target
            self.nameUTF8.removeAll(keepingCapacity: true)
            self.nameUTF8.append(contentsOf: other.nameUTF8)
        }

        func __quantize(_ paths: [String], _ at: Int) throws(GesWireError) {
            try self.pose.__quantize(paths, at + 2)
            if self.hasTarget {
            }
        }

        /// Returns whether another schema has the same wire values, so that it writes the same bytes.
        /// - Throws: `GesWireError` when a compared value has no wire value, such as a number outside its range.
        func wireEquals(_ other: Ship) throws(GesWireError) -> Bool {
            try __same(other, Self.__paths, 0)
        }

        /// Replaces every quantized value by the value its index decodes to, which a receiver reads.
        /// - Throws: `GesWireError` when a quantized value lies outside its range.
        func quantize() throws(GesWireError) {
            try __quantize(Self.__paths, 0)
        }

        func __keyOrder(_ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            try Self.__wire0(self.id, paths, at)
        }

        static func __readKeyOrder(_ reader: inout GesBitReader, _ paths: [String], _ at: Int) throws(GesWireError) -> UInt64 {
            try Self.__read0(&reader, paths, at)
        }

        /// Writes what differs from a baseline, the full record the receiver holds; `maxByteCount` bytes always suffice.
        /// - Returns: The number of bytes written.
        /// - Throws: `GesWireError` when a value does not fit its field, the keys differ, or the buffer is too small.
        func writeDelta(against baseline: Ship, into buffer: UnsafeMutableRawBufferPointer) throws(GesWireError) -> Int {
            var writer = GesBitWriter(into: buffer)
            let paths = Self.__paths
            let key = try Self.__wire0(self.id, paths, 0)
            if try key != Self.__wire0(baseline.id, paths, 0) { throw GesWireError(code: GesWireError.keyMismatch, path: paths[0]) }
            try writer.write(key, width: 16)
            _ = try __writeDelta(baseline, &writer, Self.__paths, 0, true)
            return try writer.finish()
        }

        /// Writes what differs from a baseline into a new array of its exact size.
        /// - Throws: `GesWireError` when a value does not fit its field or the keys differ.
        func deltaEncoded(against baseline: Ship) throws(GesWireError) -> [UInt8] {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(Self.maxByteCount, 1), alignment: 8)
            defer { buffer.deallocate() }
            let count = try writeDelta(against: baseline, into: buffer)
            return Array(buffer[0..<count])
        }

        /// Reads a delta against a baseline into this instance. After an error its values are unspecified.
        /// - Parameters:
        ///   - data: The delta; it may continue after it.
        ///   - baseline: The baseline, another instance.
        ///   - byteLimit: An optional limit on the bytes of this delta.
        /// - Returns: The number of bytes the delta occupies.
        /// - Throws: `GesWireError` when the data is no valid delta for this baseline.
        @discardableResult
        func readDelta(from data: UnsafeRawBufferPointer, against baseline: Ship, byteLimit: Int = .max) throws(GesWireError) -> Int {
            if self === baseline { throw GesWireError(code: GesWireError.overlappingBuffers, path: "") }
            #if DEBUG
            self.__mark(true)
            let shared = baseline.__holds()
            self.__mark(false)
            if shared { throw GesWireError(code: GesWireError.overlappingBuffers, path: "") }
            #endif
            var reader = GesBitReader(data: data, byteLimit: byteLimit)
            let paths = Self.__paths
            let key = try Self.__read0(&reader, paths, 0)
            if try key != Self.__wire0(baseline.id, paths, 0) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[0]) }
            _ = try __readDelta(baseline, &reader, Self.__paths, 0, true)
            return try reader.finish()
        }

        /// Reads a delta from bytes against a baseline into this instance. After an error its values are unspecified.
        /// - Returns: The number of bytes the delta occupies.
        /// - Throws: `GesWireError` when the bytes are no valid delta for this baseline.
        @discardableResult
        func readDelta(from bytes: [UInt8], against baseline: Ship, byteLimit: Int = .max) throws(GesWireError) -> Int {
            let buffer = UnsafeMutableRawBufferPointer.allocate(byteCount: Swift.max(bytes.count, 1), alignment: 8)
            defer { buffer.deallocate() }
            buffer.copyBytes(from: bytes)
            return try readDelta(from: UnsafeRawBufferPointer(rebasing: buffer[0..<bytes.count]), against: baseline, byteLimit: byteLimit)
        }

        func __writeDelta(_ baseline: Ship, _ writer: inout GesBitWriter, _ paths: [String], _ at: Int, _ top: Bool) throws(GesWireError) -> Bool {
            let first = writer.bitPosition
            var left = top ? 5 : 6
            while left > 0 {
                try writer.write(0, width: Swift.min(left, 64))
                left -= 64
            }
            var changed = false
            var ordinal = 0
            if !top {
                var set0 = false
                do {
                    let value0 = try Self.__wire0(self.id, paths, at)
                    let held0 = try Self.__wire0(baseline.id, paths, at)
                    if value0 != held0 {
                        try writer.write(value0, width: 16)
                        set0 = true
                    }
                }
                if set0 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            do {
                var set1 = false
                do {
                    let start1 = writer.bitPosition
                    if try self.pose.__writeDelta(baseline.pose, &writer, paths, at + 2, false) {
                        set1 = true
                    } else {
                        writer.rewind(to: start1)
                    }
                }
                if set1 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            do {
                var set5 = false
                do {
                    let value5 = try Self.__wire5(self.health, paths, at)
                    let held5 = try Self.__wire5(baseline.health, paths, at)
                    if value5 != held5 {
                        try writer.write(value5, width: 7)
                        set5 = true
                    }
                }
                if set5 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            do {
                var set6 = false
                if self.firing != baseline.firing { set6 = true }
                if set6 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            do {
                var set7 = false
                if self.hasTarget != baseline.hasTarget {
                    try writer.write(self.hasTarget ? 1 : 0, width: 1)
                    if self.hasTarget {
                        if self.target < 0 || UInt64(bitPattern: self.target) &- 0 > 65535 { throw GesWireError(code: GesWireError.outOfRange, path: paths[at + 7]) }
                        try writer.write(UInt64(bitPattern: self.target) &- 0, width: 16)
                    }
                    set7 = true
                } else if self.hasTarget {
                    let presence7 = writer.bitPosition
                    try writer.write(1, width: 1)
                    do {
                        let value7 = try Self.__wire7(self.target, paths, at)
                        let held7 = try Self.__wire7(baseline.target, paths, at)
                        if value7 != held7 {
                            try writer.write(value7, width: 16)
                            set7 = true
                        }
                    }
                    if !set7 { writer.rewind(to: presence7) }
                }
                if set7 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            do {
                var set8 = false
                if !(try __same8(baseline, paths, at)) {
                    if self.nameUTF8.count > 12 { throw GesWireError(code: GesWireError.tooLong, path: paths[at + 8]) }
                    if !self.nameUTF8.withUnsafeBytes({ GesWireRules.isValidUTF8($0) }) { throw GesWireError(code: GesWireError.invalidText, path: paths[at + 8]) }
                    try writer.write(UInt64(self.nameUTF8.count), width: 4)
                    for byte in self.nameUTF8 { try writer.write(UInt64(byte), width: 8) }
                    set8 = true
                }
                if set8 {
                    writer.setBit(first + ordinal)
                    changed = true
                }
                ordinal += 1
            }
            return changed
        }

        func __readDelta(_ baseline: Ship, _ reader: inout GesBitReader, _ paths: [String], _ at: Int, _ top: Bool) throws(GesWireError) -> Bool {
            let fieldCount = top ? 5 : 6
            try reader.require(fieldCount, path: at == 0 ? "" : paths[at - 1])
            let changeBits = reader.bitPosition
            reader.seek(to: changeBits + fieldCount)
            var changed = false
            var ordinal = 0
            if !top {
                let payload0 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set0 = try reader.read(1, path: paths[at + 0]) == 1
                reader.seek(to: payload0)
                if set0 {
                    do {
                        let held0 = try Self.__wire0(baseline.id, paths, at)
                        let value0 = try Self.__read0(&reader, paths, at)
                        if value0 == held0 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 0]) }
                        self.id = Self.__value0(value0)
                    }
                    changed = true
                } else {
                    self.id = baseline.id
                }
                ordinal += 1
            } else {
                self.id = Self.__value0(try Self.__wire0(baseline.id, paths, at))
            }
            do {
                let payload1 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set1 = try reader.read(1, path: paths[at + 1]) == 1
                reader.seek(to: payload1)
                if set1 {
                    if !(try self.pose.__readDelta(baseline.pose, &reader, paths, at + 2, false)) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 1]) }
                    changed = true
                } else {
                    self.pose = baseline.pose
                }
                ordinal += 1
            }
            do {
                let payload5 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set5 = try reader.read(1, path: paths[at + 5]) == 1
                reader.seek(to: payload5)
                if set5 {
                    do {
                        let held5 = try Self.__wire5(baseline.health, paths, at)
                        let value5 = try Self.__read5(&reader, paths, at)
                        if value5 == held5 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 5]) }
                        self.health = Self.__value5(value5)
                    }
                    changed = true
                } else {
                    self.health = baseline.health
                }
                ordinal += 1
            }
            do {
                let payload6 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set6 = try reader.read(1, path: paths[at + 6]) == 1
                reader.seek(to: payload6)
                if set6 {
                    self.firing = !baseline.firing
                    changed = true
                } else {
                    self.firing = baseline.firing
                }
                ordinal += 1
            }
            do {
                let payload7 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set7 = try reader.read(1, path: paths[at + 7]) == 1
                reader.seek(to: payload7)
                if set7 {
                    let present7 = try reader.read(1, path: paths[at + 7]) == 1
                    if !present7 && !baseline.hasTarget { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 7]) }
                    self.hasTarget = present7
                    if present7 && baseline.hasTarget {
                        do {
                            let held7 = try Self.__wire7(baseline.target, paths, at)
                            let value7 = try Self.__read7(&reader, paths, at)
                            if value7 == held7 { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 7]) }
                            self.target = Self.__value7(value7)
                        }
                    } else if present7 {
                        do {
                            let index = try reader.read(16, path: paths[at + 7])
                            self.target = Int64(bitPattern: 0 &+ index)
                        }
                    } else {
                        self.target = 0
                    }
                    changed = true
                } else {
                    self.hasTarget = baseline.hasTarget
                    self.target = baseline.target
                }
                ordinal += 1
            }
            do {
                let payload8 = reader.bitPosition
                reader.seek(to: changeBits + ordinal)
                let set8 = try reader.read(1, path: paths[at + 8]) == 1
                reader.seek(to: payload8)
                if set8 {
                    do {
                        let count = Int(try reader.read(4, path: paths[at + 8]))
                        if count > 12 { throw GesWireError(code: GesWireError.invalidCount, path: paths[at + 8]) }
                        try reader.require(count * 8, path: paths[at + 8])
                        self.nameUTF8.removeAll(keepingCapacity: true)
                        for _ in 0..<count { self.nameUTF8.append(UInt8(truncatingIfNeeded: try reader.read(8, path: paths[at + 8]))) }
                        if !self.nameUTF8.withUnsafeBytes({ GesWireRules.isValidUTF8($0) }) { throw GesWireError(code: GesWireError.invalidText, path: paths[at + 8]) }
                    }
                    if try __same8(baseline, paths, at) { throw GesWireError(code: GesWireError.invalidDelta, path: paths[at + 8]) }
                    changed = true
                } else {
                    self.nameUTF8.removeAll(keepingCapacity: true)
                    self.nameUTF8.append(contentsOf: baseline.nameUTF8)
                }
                ordinal += 1
            }
            return changed
        }
    }
}
